export interface StockData {
  date: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  MA5: number;
  MA120: number;
  MA10: number;
  MA20: number;
  MA50: number;
  MA100: number;
  MA200: number;
  MA300?: number;
  RSI: number;
  StochRSI_K: number;
  StochRSI_D: number;
  MACDLine: number;
  SignalLine: number;
  divergence: number;
  MACDDivergence: any;
  MA50_Angle?: any;
  MA20_Angle?: any;
}
export interface StockQuoteFMP {
  symbol: string;
  price: number;
  name: string;
  change: number;
  changesPercentage: number;
  exchange: string;
}

export interface EarningsCalendar {
  symbol: string;
  date: string; // YYYY-MM-DD
  hour: string;
  quarter: number;
  year: number;
  epsEstimate: number | null;
  epsActual: number | null;
  revenueEstimate: number | null;
  revenueActual: number | null;
}

export interface CompanyProfile {
  symbol: string;
  name: string;
  marketCap: number;
}

